  'sso.backup.hint': "Jika penyedia identiti anda berhenti berfungsi, sehingga dua pentadbir yang dipilih di sini masih boleh log masuk: dengan pautan e-mel dan kemudian kunci laluan atau aplikasi pengesah mereka, tidak pernah dengan pautan sahaja. Setiap log masuk sedemikian dicatat dalam log aktiviti dan dihantar melalui e-mel kepada pentadbir lain.",
