  'sso.test.why.oauth_failed': "penyedia anda tidak menyelesaikan log masuk.",
  'sso.test.why.no_account': "jawapan tidak membawa alamat e-mel (semak atribut e-mel).",
  'sso.test.why.not_configured': "butiran penyedia tidak lengkap.",
  "sso.test.why.bad_secret": "penyedia anda menolak Client secret (mungkin telah diperbaharui di sana). Tampal yang semasa ke dalam “Client secret” dan simpan.",
  "sso.test.why.bad_signature": "tandatangan tidak sepadan dengan yang disimpan di sini (penyedia mungkin telah memperbaharui kunci atau sijilnya). Untuk SAML, tampal sijil baharu ke dalam “Sijil tandatangan IdP” dan simpan.",
  "sso.test.why.bad_token": "jawapan itu untuk aplikasi lain atau sudah tamat tempoh. Semak “Issuer” dan “Client ID”, dan pastikan jam penyedia betul.",
  "sso.test.why.idp_unreachable": "penyedia anda tidak dapat dihubungi atau sedang sibuk. Semak alamat token dan kunci; jika betul, tunggu seminit.",
