  'perm.data.export': "Eksport data",
  'perm.data.export.hint': "Muat turun pelanggan, rekod, tugasan dan laporan sebagai Excel atau CSV. Fail hanya mengandungi apa yang boleh dilihat oleh orang ini, dan setiap eksport ditulis dalam log aktiviti.",
