  'demo.hub.hero.title': "Ikuti lawatan. Inilah produk sebenar.",
  'demo.hub.hero.lead': "Setiap lawatan berjalan pada aplikasi langsung dalam pelayar anda, dengan syarikat rekaan dan pelanggannya. Tiada apa untuk dipasang, tiada apa dihantar ke mana-mana — dan anda boleh keluar daripada lawatan untuk klik di mana-mana bila-bila masa.",
