  'demo.hub.card.start': "Mulakan lawatan",
  'demo.hub.card.meta': "{m} min · {s} langkah",
  'demo.hub.band.title': "Sudah cukup melihat? Cuba dengan pelanggan anda sendiri.",
  'demo.hub.band.text': "Minta ruang kerja untuk pasukan anda: tiga bulan percuma, tiada kad diperlukan, dalam sebelas bahasa.",
  'demo.hub.band.primary': "Mula percuma",
  'demo.hub.band.secondary': "Baca dokumen",
  'demo.hub.foot.home': "Laman utama Curahold",
  'demo.hub.foot.privacy': "Privasi",
  'demo.hub.foot.terms': "Terma",
  'demo.hub.foot.made': "Semua dalam lawatan ini adalah rekaan: syarikat, orangnya dan pelanggannya.",
  'demo.hub.lang.title': "Pilih bahasa anda",
  'demo.hub.lang.note': "Seluruh demo — termasuk syarikat contoh — berjalan dalam bahasa yang anda pilih. Anda boleh mengubahnya bila-bila masa daripada butang bahasa.",
  'demo.hub.lang.button': "Bahasa: {name}",
