  'docs.section.releases': "Nota keluaran",
  'docs.section.legal': "Undang-undang",
  'docs.lead': "Semua yang anda perlukan untuk menggunakan Curahold, menyediakannya untuk pasukan anda dan menyambungkannya kepada alat anda sendiri.",
  'docs.start.help': "Gunakan Curahold setiap hari: pelanggan, tugasan, papan, laporan dan portal pelanggan.",
  'docs.start.developers': "Sambungkan sistem anda sendiri: kunci, webhook dan permintaan pertama dalam lima minit.",
  'docs.start.reference': "Setiap alamat, medan demi medan, dibina daripada kod produk itu sendiri.",
  'docs.connections.title': "Sambungan",
  'docs.connections.text': "CRM, hamparan, aplikasi sembang, meja sokongan dan alat yang tiada dalam senarai.",
