  'docs.ask.open': "Tanya",
  'docs.ask.title': "Tanya Curahold",
  'docs.ask.close': "Tutup",
  'docs.ask.hello': "Tanya cara melakukan sesuatu dalam Curahold, dengan kata-kata anda sendiri. Saya menjawab daripada dokumen ini dan menunjukkan dari mana setiap jawapan datang.",
  'docs.ask.hi': "Helo! Apa yang anda mahu lakukan dalam Curahold?",
  'docs.ask.thanks': "Gembira dapat membantu. Tanyalah lagi bila-bila masa.",
  'docs.ask.empty': "Tulis beberapa perkataan tentang apa yang anda mahu lakukan.",
