  'docs.ask.you': "Anda",
  'docs.ask.ai': "Ditulis oleh AI daripada dokumen ini. Semak sumbernya untuk apa-apa yang penting.",
  'trialMail.approved.subject': "Percubaan Curahold anda untuk {company} sudah sedia",
  'trialMail.approved.body': "Hai {name},\n\nBerita baik: percubaan Curahold anda untuk {company} sudah sedia. Ia memuatkan {seats} orang dan berjalan sehingga {until}.\n\nLog masuk dengan pautan ini untuk menyediakan syarikat anda. Ia berfungsi sekali, selama 7 hari:\n\n{link}\n\nSetelah masuk, pelan persediaan membimbing anda menjemput pasukan anda dan menyambungkan alat anda. Balas sahaja e-mel ini jika anda ada soalan.\n\nPasukan Curahold",
  'trialMail.rejected.subject': "Tentang permintaan percubaan Curahold anda untuk {company}",
  'trialMail.rejected.body': "Hai {name},\n\nTerima kasih atas minat anda terhadap Curahold dan masa yang anda luangkan untuk memberitahu kami tentang {company}.\n\nKami tidak dapat memulakan percubaan untuk permintaan ini buat masa ini. Ini bukan penilaian terhadap pasukan anda: kami membuka percubaan secara berperingkat, supaya setiap syarikat mendapat bantuan yang sewajarnya dari hari pertama.\n\nKami akan menyimpan butiran anda dan menghubungi anda apabila kami dapat menawarkan percubaan yang sesuai. Jika ada apa-apa yang berubah di pihak anda, balas sahaja e-mel ini.\n\nSalam hormat,\nPasukan Curahold",
  'trial.side.title': "Percubaan percuma anda, dalam lima langkah ringkas",
  'trial.side.foot': "Tiga bulan percuma · tiada kad · data anda kekal milik anda",
  'trial.step.email': "E-mel kerja",
  'trial.step.you': "Tentang anda",
  'trial.step.company': "Syarikat anda",
  'trial.step.use': "Percubaan anda",
  'trial.step.consent': "Semak dan hantar",
  'trial.progress': "Langkah {n} daripada {total}",
  'trial.title': "Minta percubaan percuma anda",
  'trial.lead': "Tiga bulan dengan semua ciri dihidupkan. Kami sendiri membaca setiap permintaan dan membalas dalam satu hari bekerja.",
  'trial.email.label': "E-mel kerja",
  'trial.email.send': "Hantar kod",
  'trial.code.label': "Kod 6 digit",
  'trial.code.sent': "Kami telah menghantar kod ke {email}. Ia berfungsi selama {minutes} minit.",
  'trial.code.verify': "Sahkan",
  'trial.code.again': "Hantar kod baharu",
  'trial.code.change': "Gunakan alamat lain",
  'trial.code.wrong': "Kod itu tidak betul atau telah tamat tempoh. Cuba lagi, atau minta yang baharu.",
  'trial.code.verified': "Disahkan: {email}",
