  'perm.finance.view.hint': "Baki terbuka, invois tertunggak dan pembayaran daripada program perakaunan yang disambungkan, pada halaman setiap pelanggan. Tanpanya, orang hanya melihat berapa hari pembayaran lewat, dalam skor kesihatan.",
