  'fin.addHint': "Baca sahaja: baki terbuka, invois tertunggak dan pembayaran dipaparkan pada halaman setiap pelanggan, dan pembayaran lewat boleh dikira dalam skor kesihatan. Tiada apa pernah ditulis ke program itu.",
