  'fin.file.start': "Muat naik fail",
  'fin.what.zohobooks': "Pelanggan, invois dan pembayaran daripada Zoho Books, di setiap pusat data Zoho.",
  'fin.what.xero': "Pelanggan, invois jualan dan pembayaran daripada Xero.",
  'fin.what.odoo': "Pelanggan, invois dan pembayaran daripada Odoo Online, Odoo.sh atau pelayan anda sendiri.",
