  'fin.what.parasut': "Pelanggan, invois jualan dan pembayaran daripada Paraşüt.",
  'fin.what.quickbooks': "Pelanggan, invois dan pembayaran daripada QuickBooks Online.",
  'fin.what.finfile': "AutoCount, SQL Account, Logo, Mikro, SAP Business One atau mana-mana program lain: muat naik eksport Excel atau CSV.",
  'fin.steps.zohobooks': "Log masuk dengan akaun Zoho yang boleh melihat organisasi Zoho Books anda.\nBenarkan Curahold membaca kenalan, invois dan pembayaran. Ia hanya meminta akses baca.\nKembali di sini, mulakan bacaan pertama dan semak pelanggan yang tidak dapat dipadankan.",
  'fin.steps.xero': "Log masuk ke Xero dan pilih organisasi untuk disambungkan.\nBenarkan akses baca kepada kenalan dan transaksi; Curahold tidak boleh mengubah apa-apa dalam Xero.\nKembali di sini, mulakan bacaan pertama dan semak pelanggan yang tidak dapat dipadankan.",
  'fin.steps.freee': "Log masuk ke freee dan pilih syarikat (事業所) untuk disambungkan.\nBenarkan akses; Curahold hanya membaca rakan kongsi dan urus niaga jualan.\nKembali di sini, mulakan bacaan pertama dan semak pelanggan yang tidak dapat dipadankan.",
  'fin.steps.quickbooks': "Log masuk ke Intuit dan pilih syarikat QuickBooks untuk disambungkan.\nBenarkan akses kepada data perakaunan; Curahold hanya membaca pelanggan, invois dan pembayaran.\nKembali di sini, mulakan bacaan pertama dan semak pelanggan yang tidak dapat dipadankan.",
  'fin.steps.odoo': "Dalam Odoo, buka profil anda → Preferences → Account Security dan cipta API key.\nCatat alamat Odoo dan log masuk anda. Pada Odoo.sh atau pelayan anda sendiri, juga nama pangkalan data.\nMasukkannya di bawah. Pada Odoo Online, akses API memerlukan pelan Custom (peraturan Odoo).",
  'fin.steps.parasut': "Minta akses API untuk syarikat anda daripada sokongan Paraşüt; mereka menghantar client ID dan client secret.\nNombor syarikat anda ada dalam bar alamat selepas uygulama.parasut.com/.\nMasukkannya bersama e-mel dan kata laluan pengguna Paraşüt. Kata laluan digunakan sekali untuk mendapatkan kunci dan tidak disimpan.",
  'fin.steps.finfile': "Eksport pelanggan, invois dan pembayaran daripada program anda sebagai Excel atau CSV.\nLetakkannya dalam lajur templat; anda boleh memuat turun templat pada skrin seterusnya.\nMuat naik pelanggan dahulu, kemudian invois, kemudian pembayaran. Muat naik fail baharu bila-bila masa anda mahu angka yang lebih terkini.",
