  'demo.tour.role.seller': "Jualan dalaman",
  'demo.tour.role.product': "Produk",
  'demo.tour.sprint.title': "Rancang sprint, perhatikan burndown-nya",
  'demo.tour.sprint.blurb': "Backlog pasukan produk berbanding kapasitinya, sprint yang sedang berjalan dengan carta yang menunjukkan skop yang diambilnya, dan minggu-minggu akan datang pasukan.",
  'demo.tour.sprint.1.title': "Sprint seterusnya, daripada backlog",
  'demo.tour.sprint.1.body': "Pilih cerita untuk sprint seterusnya di sini; sasaran dan rentak biasa pasukan berada di sebelahnya.",
  'demo.tour.sprint.2.title': "Kapasiti sebelum komitmen",
  'demo.tour.sprint.2.body': "Bar terisi apabila cerita dimasukkan, dan memberitahu apabila sprint memegang lebih banyak mata daripada yang biasa diselesaikan pasukan.",
  'demo.tour.sprint.3.title': "Burndown yang berkata benar",
  'demo.tour.sprint.3.body': "Kerja yang ditambah di pertengahan dipaparkan sebagai langkah naik, jadi sprint yang lewat dapat dijelaskan dan bukan diteka.",
  'demo.tour.sprint.4.title': "Minggu-minggu akan datang, orang demi orang",
  'demo.tour.sprint.4.body': "Tugasan terbuka mengikut minggu tarikh akhirnya, berapa banyak yang dijanjikan kepada pelanggan, dan matanya: siapa ada ruang sebelum anda merancang lagi.",
  'demo.tour.handover.title': "Daripada urus niaga yang dimenangi kepada pasukan pelanggan",
  'demo.tour.handover.blurb': "Jualan menutup urus niaga; orang yang menjaga pelanggan menyambungnya pada halaman yang sama, tanpa ada yang tercicir.",
  'demo.tour.handover.1.title': "Urus niaga mengikut peringkat",
  'demo.tour.handover.1.body': "Setiap lajur ialah peringkat. Seret urus niaga ke Dimenangi apabila ia ditutup.",
  'demo.tour.handover.2.title': "Urus niaga membawa kisahnya",
  'demo.tour.handover.2.body': "Siapa yang terlibat, apa yang dijanjikan dan bila ia diperbaharui kekal bersama urus niaga, untuk sesiapa yang mengambilnya seterusnya.",
  'demo.tour.handover.3.title': "Paparan pasukan pelanggan",
  'demo.tour.handover.3.body': "Pelanggan berada di sini sebaik sahaja urus niaga dimenangi: pemilik, kesihatan dan janji seterusnya pada satu kad.",
  'demo.tour.handover-loop.title': "Daripada urus niaga yang dimenangi kepada “kami membinanya untuk anda”",
  'demo.tour.handover-loop.blurb': "Kad serahan apabila Jualan menang, permintaan yang dipautkan kepada kerja Produk, dan mesej balas apabila ia dikeluarkan.",
  'demo.tour.handover-loop.1.title': "Jualan baru memenangi yang ini",
  'demo.tour.handover-loop.1.body': "Cedarmoor Health menandatangani pembaharuan dua tahun pada saluran Jualan. Buka pelanggan.",
  'demo.tour.handover-loop.2.title': "Satu kad, tiada yang tercicir",
  'demo.tour.handover-loop.2.body': "Orang dan pendirian mereka, apa yang dijanjikan Jualan, apa yang masih mereka tunggu daripada Produk, tarikh dan perbualan jualan terkini. Tiada sesiapa perlu menulisnya.",
  'demo.tour.handover-loop.3.title': "Sahkan, dan ia mempunyai pemilik",
  'demo.tour.handover-loop.3.body': "Pilih siapa yang mengambil alih dalam Kejayaan Pelanggan (atau Onboarding, jika syarikat anda memilikinya) dan playbook untuk dimulakan. Ctrl+Enter melakukannya dari mana-mana pada kad.",
  'demo.tour.handover-loop.4.title': "Pelanggan yang meminta sesuatu",
  'demo.tour.handover-loop.4.body': "Quillfield Retail meminta dua perkara daripada Produk. Bukanya.",
  'demo.tour.handover-loop.5.title': "Apa yang mereka tunggu",
  'demo.tour.handover-loop.5.body': "Janji dan kerja produk yang mereka minta: status, tamat sprint dan jabatan, kelihatan kepada sesiapa yang melihat pelanggan, tanpa membuka papan Produk.",
  'demo.tour.handover-loop.6.title': "Sudah dikeluarkan: beritahu mereka",
  'demo.tour.handover-loop.6.body': "Apabila kerja selesai, pemilik menerima tugasan dan draf mesej ini. Salinnya ke e-mel anda, atau tutup permintaan portal mereka. Tiada apa dihantar dengan sendirinya.",
  'demo.tour.handover-loop.7.title': "Pautkan permintaan seterusnya",
  'demo.tour.handover-loop.7.body': "Cari kerja Produk dan pautkan permintaan dengan dua ketukan kekunci. Backlog Produk kemudian menunjukkan berapa ramai pelanggan menunggu, nilai mereka dan siapa yang diperbaharui paling awal.",
  'demo.tour.move-in.title': "Bawa fail anda sendiri",
  'demo.tour.move-in.blurb': "Lepaskan eksport daripada alat yang anda gunakan sekarang dan lihat kerja anda sendiri dalam Curahold. Dalam demo ia tidak pernah meninggalkan peranti anda.",
  'demo.tour.move-in.1.title': "Mana-mana eksport, satu tempat",
  'demo.tour.move-in.1.body': "Lepaskan CSV, helaian Excel atau eksport JSON papan di sini. Curahold membezakan pelanggan daripada tugasan melalui nama lajur fail.",
  'demo.tour.move-in.2.title': "Fail anda kekal bersama anda",
  'demo.tour.move-in.2.body': "Seluruh demo berjalan dalam tab pelayar ini. Tiada apa dimuat naik; memuat semula halaman akan melupakannya.",
  'demo.tour.move-in.3.title': "Semak sebelum apa-apa disimpan",
  'demo.tour.move-in.3.body': "Subtugasan, ulasan, medan anda sendiri dan pautan “menunggu” turut dibawa. Larian percubaan menyatakan apa yang akan masuk dan apa yang tidak, dan empat puluh senarai digabungkan ke dalam beberapa papan jabatan.",
  'demo.tour.team-load.title': "Siapa ada ruang, dan pelanggan mana menunggu",
  'demo.tour.team-load.blurb': "Minggu-minggu akan datang orang demi orang, dan kerja terbuka, permintaan dan tiket setiap pelanggan pada satu halaman.",
  'demo.tour.team-load.1.title': "Minggu-minggu akan datang",
  'demo.tour.team-load.1.body': "Setiap sel ialah minggu seseorang: tugasan terbuka yang tamat ketika itu, yang dijanjikan kepada pelanggan, dan mata. Warna menunjukkan lebih berat atau lebih ringan daripada biasa.",
  'demo.tour.team-load.2.title': "Setiap pelanggan sekali gus",
