  'demo.tour.onboarding-hub.title': "Pelan permulaan anda",
  'demo.tour.onboarding-hub.blurb': "Satu pelan bersama: perkara seterusnya untuk dilakukan, giliran siapa, langkah yang ditanda sendiri, isu bersama dan semakan data.",
  'demo.tour.onboarding-hub.1.title': "Satu perkara untuk dilakukan seterusnya",
  'demo.tour.onboarding-hub.1.body': "Sentiasa di atas: langkah terbuka seterusnya, giliran siapa dan berapa lama, dan satu butang yang membawa anda ke sana.",
  'demo.tour.onboarding-hub.2.title': "Kemajuan berwajaran",
  'demo.tour.onboarding-hub.2.body': "Langkah wajib dikira sepenuhnya, langkah pilihan separuh. Titik menandakan apa yang dijangka hari ini, dan pembilang menunjukkan siapa yang ditunggu.",
  'demo.tour.onboarding-hub.3.title': "Langkah yang ditanda sendiri",
