  'demo.tour.onboarding-hub.4.title': "Isu bersama",
  'demo.tour.onboarding-hub.4.body': "Setiap satu menyatakan giliran siapa. Ujian persediaan yang gagal ialah satu baris di sini, dengan butang untuk menguji semula; isu boleh menjadi tiket sokongan, tidak pernah salinannya.",
