  "hooks.title": "Webhook masuk",
  "hooks.lede": "Untuk sebarang alat yang boleh memanggil alamat web: tandatangan elektronik, telefon, sembang, pembayaran, Zapier, Make atau kod anda sendiri. Setiap penghantaran menjadi tugasan, tiket, catatan pada pelanggan atau nota pada urus niaga; item yang sama dihantar semula akan mengemas kininya.",
