  "hooks.how.curahold": "Dalam Zapier gunakan “Webhooks by Zapier → POST”, dalam Make “HTTP → Make a request”. Tandatangani badan mesej: X-Curahold-Signature: t=<saat unix>,v1=<HMAC-SHA256 hex bagi \"t.body\" dengan rahsia>. Tambah X-Curahold-Event-Id supaya cubaan semula hanya digunakan sekali.",
  "hooks.how.esign": "Dalam DocuSign: Settings → Connect → Add Configuration → Custom. Tampal alamat sebagai URL to publish to, pilih JSON, tandakan Envelope Sent, Completed, Declined dan Voided, dan hidupkan HMAC dengan kunci yang anda taip di sini.",
  "hooks.how.aircall": "Dalam Aircall: Integrations → Webhook → Install. Tampal alamat, tandakan call.ended, dan tampal token webhook itu di sini.",
  "hooks.how.tawkto": "Dalam Tawk.to: Administration → Settings → Webhooks → Create webhook. Tampal alamat, tandakan Chat end dan Ticket create, dan tampal secret key di sini.",
  "hooks.how.razorpay": "Dalam Razorpay: Accounts & Settings → Webhooks → Add New Webhook. Tampal alamat, taip satu rahsia (yang sama di sini), tandakan payment.captured dan payment.failed.",
  "hooks.how.custom": "Hantar JSON ke alamat itu dengan rahsia dalam pengepala X-Curahold-Token (atau ?token= dalam alamat jika alat itu tidak dapat menetapkan pengepala).",
